#pragma once

#include "CompletionStage.h"
#include "Future.h"
#include "TimeUnit.h"

#include <chrono>
#include <exception>
#include <functional>
#include <future>
#include <memory>
#include <mutex>
#include <stdexcept>
#include <utility>
#include <vector>

// java.util.concurrent.CompletableFuture 模板桩。
// 同时实现 Future 与 CompletionStage：
// - 内部用 std::promise + std::shared_future 承载结果，支持阻塞 get 与超时 get；
// - mutex 保护完成状态与回调列表，完成（正常/异常/取消）时按注册顺序触发回调；
// - whenComplete/thenCompose 返回带空 deleter 的别名 shared_ptr，
//   因此 CompletableFuture 对象可被任意方式持有（栈、new 或 shared_ptr）。
template<typename T>
class CompletableFuture : public Future<T>, public CompletionStage<T> {
public:
    CompletableFuture()
        : promise_(std::make_shared<std::promise<T>>()),
          future_(promise_->get_future().share()) {}

    // 静态工厂：返回一个已正常完成的 CompletableFuture
    static std::shared_ptr<CompletableFuture<T>> completedFuture(T value) {
        auto cf = std::make_shared<CompletableFuture<T>>();
        cf->complete(value);
        return cf;
    }

    // 正常完成；若已完成（含取消）则返回 false
    bool complete(T value) {
        std::vector<std::function<void(T, std::exception_ptr)>> callbacks;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (done_) return false;
            done_ = true;
            value_ = value;
            callbacks.swap(callbacks_);
        }
        // done_ 已保证 promise 只会被设置一次，set_value 不会抛 future_error
        promise_->set_value(value);
        for (auto& cb : callbacks) cb(value, nullptr);
        return true;
    }

    // 异常完成；若已完成（含取消）则返回 false
    bool completeExceptionally(std::exception_ptr ex) {
        std::vector<std::function<void(T, std::exception_ptr)>> callbacks;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (done_) return false;
            done_ = true;
            error_ = ex;
            callbacks.swap(callbacks_);
        }
        promise_->set_exception(ex);
        for (auto& cb : callbacks) cb(T{}, ex);
        return true;
    }

    // 阻塞等待结果；异常完成或被取消时重新抛出对应异常
    T get() override { return future_.get(); }

    // 带超时的阻塞等待；超时抛 std::runtime_error
    T get(long timeout, TimeUnit unit) {
        auto status = future_.wait_for(std::chrono::nanoseconds(unit.toNanos(timeout)));
        if (status != std::future_status::ready)
            throw std::runtime_error("CompletableFuture::get 超时");
        return future_.get();
    }

    bool isDone() override {
        std::lock_guard<std::mutex> lock(mutex_);
        return done_;
    }

    // 取消：未完成时标记取消并以异常方式完成（get 将抛异常），已完成返回 false
    bool cancel(bool /*mayInterruptIfRunning*/) override {
        std::vector<std::function<void(T, std::exception_ptr)>> callbacks;
        std::exception_ptr ex =
            std::make_exception_ptr(std::runtime_error("CompletableFuture 已取消"));
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (done_) return false;
            done_ = true;
            cancelled_ = true;
            error_ = ex;
            callbacks.swap(callbacks_);
        }
        promise_->set_exception(ex);
        for (auto& cb : callbacks) cb(T{}, ex);
        return true;
    }

    bool isCancelled() {
        std::lock_guard<std::mutex> lock(mutex_);
        return cancelled_;
    }

    // 注册完成回调；若已完成则在调用线程立即执行
    std::shared_ptr<CompletionStage<T>> whenComplete(
        std::function<void(T, std::exception_ptr)> action) override {
        bool callNow = false;
        T valueSnapshot{};
        std::exception_ptr errorSnapshot;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            if (done_) {
                // done_ 不可逆，value_/error_ 此后稳定，可直接取快照
                callNow = true;
                valueSnapshot = value_;
                errorSnapshot = error_;
            } else {
                callbacks_.push_back(action);
            }
        }
        if (callNow) action(valueSnapshot, errorSnapshot);
        // 空 deleter 别名指针：不接管生命周期，仅满足 CompletionStage 返回类型
        return std::shared_ptr<CompletionStage<T>>(this, [](CompletionStage<T>*) {});
    }

    // thenCompose 的实现入口（由 CompletionStage<T>::thenCompose 转发调用）。
    // 同步语义：本阶段完成时立即执行 fn 并把其结果阶段桥接到返回值上。
    template<typename U>
    std::shared_ptr<CompletionStage<U>> thenComposeImpl(
        std::function<std::shared_ptr<CompletionStage<U>>(T)> fn) {
        auto result = std::make_shared<CompletableFuture<U>>();
        whenComplete([fn, result](T v, std::exception_ptr ex) {
            if (ex) {
                result->completeExceptionally(ex);
                return;
            }
            try {
                auto next = fn(v);
                auto nextCf = std::dynamic_pointer_cast<CompletableFuture<U>>(next);
                if (!nextCf) {
                    result->completeExceptionally(std::make_exception_ptr(std::logic_error(
                        "thenCompose: 不支持的 CompletionStage 实现")));
                    return;
                }
                // 桥接下一阶段的结果到 result
                nextCf->whenComplete([result](U uv, std::exception_ptr uex) {
                    if (uex) result->completeExceptionally(uex);
                    else result->complete(uv);
                });
            } catch (...) {
                result->completeExceptionally(std::current_exception());
            }
        });
        return result;
    }

private:
    std::shared_ptr<std::promise<T>> promise_;   // 结果写入端
    std::shared_future<T> future_;               // 结果读取端（可多次 get）
    std::mutex mutex_;                           // 保护以下状态
    bool done_ = false;                          // 是否已完成（含取消），不可逆
    bool cancelled_ = false;
    T value_{};                                  // 正常完成时的结果快照
    std::exception_ptr error_;                   // 异常完成/取消时的异常
    std::vector<std::function<void(T, std::exception_ptr)>> callbacks_;
};

// CompletionStage<T>::thenCompose 的延迟定义：
// 依赖 CompletableFuture 完整类型，因此放在本头文件末尾（模板，随用随实例化）。
template<typename T>
template<typename U>
std::shared_ptr<CompletionStage<U>> CompletionStage<T>::thenCompose(
    std::function<std::shared_ptr<CompletionStage<U>>(T)> fn) {
    auto self = dynamic_cast<CompletableFuture<T>*>(this);
    if (!self)
        throw std::logic_error("CompletionStage::thenCompose 仅支持 CompletableFuture 实现");
    return self->template thenComposeImpl<U>(std::move(fn));
}
